script:
await step('Mở màn hình Cấu hình cửa hàng SCM (/scm/config/store)', async () => {
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const txt = await page.locator('body').innerText();
  assert(txt.length > 50, 'Không tải được màn hình Cấu hình cửa hàng SCM');
});

await step('Mở màn hình Cấu hình phụ trách theo chức danh SCM (/scm/config/employee)', async () => {
  await page.goto('https://tasks.zuizui.io/scm/config/employee', { waitUntil: 'domcontentloaded' });
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const txt = await page.locator('body').innerText();
  assert(txt.length > 50, 'Không tải được màn hình Cấu hình phụ trách SCM');
});

await step('Mở màn hình Cấu hình Đơn vị tạo phiếu SCM (/scm/config/unit)', async () => {
  await page.goto('https://tasks.zuizui.io/scm/config/unit', { waitUntil: 'domcontentloaded' });
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const txt = await page.locator('body').innerText();
  assert(txt.length > 50, 'Không tải được màn hình Đơn vị tạo phiếu SCM');
  ctx.log('Đã kiểm tra các màn hình cấu hình phụ trách và đơn vị của SCM.');
});
